import { cn } from "cn";
import { getBrandImage, type BrandImageSlug } from "@/data/images";

/**
 * Renders a manifest image from /public/images/brand.
 * Uses a <picture> element (AVIF + WebP + fallback) because variants are
 * pre-generated by scripts/process-images.mjs; next/image would re-encode
 * them at runtime for no benefit. Alt text comes from data/images.ts.
 *
 * - `blend="multiply"` is only valid on light (white/blush) sections.
 * - Never place text directly over the photo without an overlay that meets AA.
 * - `priority` sets fetchpriority=high + eager loading (use for LCP only).
 * - `decorative` renders alt="" for purely ornamental use.
 */
export function BrandImage({
  slug,
  variant = "rounded",
  sizes = "100vw",
  priority = false,
  blend,
  decorative = false,
  className,
  imgClassName,
  ratio,
  fill = false,
  reveal = true,
}: {
  slug: BrandImageSlug;
  variant?: "arch" | "circle" | "rounded" | "bleed";
  sizes?: string;
  priority?: boolean;
  blend?: "multiply";
  decorative?: boolean;
  className?: string;
  imgClassName?: string;
  /** e.g. "4/5" forces a crop instead of the natural aspect ratio. */
  ratio?: string;
  /** Cover the nearest positioned ancestor edge-to-edge (object-cover). */
  fill?: boolean;
  reveal?: boolean;
}) {
  const image = getBrandImage(slug);
  if (image.parked || !image.src) return null;

  const aspectRatio = ratio ?? `${image.width} / ${image.height}`;

  return (
    <div
      className={cn(
        fill ? "absolute inset-0" : "relative",
        "overflow-hidden",
        variant === "arch" && "rounded-t-[10rem] rounded-b-2xl",
        variant === "circle" && "rounded-full",
        variant === "rounded" && "rounded-2xl",
        variant === "bleed" && "rounded-none",
        reveal && "reveal",
        className
      )}
      style={{
        ...(image.hasAlpha
          ? {}
          : {
              backgroundImage: `url(${image.blur})`,
              backgroundSize: "cover",
            }),
        ...(fill ? {} : { aspectRatio }),
      }}
    >
      <picture>
        <source type="image/avif" srcSet={image.srcSetAvif} sizes={sizes} />
        <source type="image/webp" srcSet={image.srcSetWebp} sizes={sizes} />
        <img
          src={image.src}
          alt={decorative ? "" : image.alt}
          width={image.width}
          height={image.height}
          sizes={sizes}
          loading={priority ? "eager" : "lazy"}
          fetchPriority={priority ? "high" : "auto"}
          decoding="async"
          className={cn(
            ratio || fill
              ? "absolute inset-0 size-full object-cover"
              : "h-auto w-full object-cover",
            blend === "multiply" && "mix-blend-multiply",
            imgClassName
          )}
          style={{
            objectPosition: `${image.focal.x}% ${image.focal.y}%`,
          }}
        />
      </picture>
    </div>
  );
}
